   if (is_https)
   {
      /* This build has no TLS: front remote servers with a TLS-terminating
       * proxy and point at its http:// address. */
      fprintf(stderr, "aimee: https:// is not supported in this build; use http:// "
                      "behind a TLS-terminating proxy\n");
      return NULL;
   }
#endif

